import moment from 'moment-timezone'
import dayjs from '../../src'
import utc from '../../src/plugin/utc'
import timezone from '../../src/plugin/timezone'

dayjs.extend(utc)
dayjs.extend(timezone)

const zones = ['America/Los_Angeles', 'America/New_York', 'Europe/London', 'Asia/Kolkata', 'Asia/Kathmandu', 'Australia/Lord_Howe', 'Pacific/Chatham', 'Asia/Tehran', 'Australia/Sydney', 'Africa/Cairo', 'America/Santiago', 'Asia/Tokyo', 'UTC', 'Pacific/Auckland', 'America/St_Johns', 'Asia/Yangon', 'Europe/Paris', 'America/Whitehorse', 'Africa/Monrovia', 'Asia/Katmandu']
const stamps = ['2014-06-01T12:00:00Z', '2014-01-01T00:00:00Z', '1969-12-31T23:59:59Z', '1960-06-01T12:00:00Z', '1900-01-01T00:00:00Z', '2035-06-01T12:00:00Z', '2014-06-01T00:00:00Z', '2014-12-31T23:59:59Z', '2014-03-09T10:00:00Z', '2014-11-02T05:00:00Z']

const cmp = (label, a, b, out) => {
  if (a !== b) out.push(`${label}: ${JSON.stringify(a)} != ${JSON.stringify(b)}`)
}

it('exhaustive', () => {
  const out = []
  zones.forEach((tz) => {
    stamps.forEach((s) => {
      const ts = Date.parse(s)
      // convert path
      const d = dayjs(s).tz(tz)
      const m = moment(s).tz(tz)
      cmp(`convert ${tz} ${s} fmt`, d.format(), m.format(), out)
      cmp(`convert ${tz} ${s} Z`, d.format('Z'), m.format('Z'), out)
      cmp(`convert ${tz} ${s} val`, d.valueOf(), m.valueOf(), out)
      cmp(`convert ${tz} ${s} off`, d.utcOffset(), m.utcOffset(), out)
      // parse path (wall clock)
      const wall = s.replace('T', ' ').replace('Z', '')
      const d2 = dayjs.tz(wall, tz)
      const m2 = moment.tz(wall, tz)
      cmp(`parse ${tz} ${wall} fmt`, d2.format(), m2.format(), out)
      cmp(`parse ${tz} ${wall} Z`, d2.format('Z'), m2.format('Z'), out)
      cmp(`parse ${tz} ${wall} val`, d2.valueOf(), m2.valueOf(), out)
      // timestamp / Date
      const d3 = dayjs.tz(ts, tz)
      const m3 = moment.tz(ts, tz)
      cmp(`ts ${tz} ${s} fmt`, d3.format(), m3.format(), out)
      cmp(`ts ${tz} ${s} Z`, d3.format('Z'), m3.format('Z'), out)
      cmp(`ts ${tz} ${s} val`, d3.valueOf(), m3.valueOf(), out)
      const d4 = dayjs.tz(new Date(ts), tz)
      const m4 = moment.tz(new Date(ts), tz)
      cmp(`date ${tz} ${s} fmt`, d4.format(), m4.format(), out)
      cmp(`date ${tz} ${s} val`, d4.valueOf(), m4.valueOf(), out)
    })
  })
  console.log('MISMATCHES', out.length)
  out.slice(0, 40).forEach(l => console.log(l))
})
EOF
